      </div>

      <FeatureGridBlock
        data={{ heading: "Why teams choose us", features }}
        variant="feature_grid_3up"
      />
      <TestimonialSectionBlock
        data={{ heading: "What customers say", testimonials }}
        variant="testimonial_grid"
      />
