        <InnerContent label={`spacing="${spacing}"`} />
      </Section>
    ))}
  </div>
);

const WithBackground = () => (
  <Section
    spacing="lg"
    style={{ background: "var(--section-cta-bg, #4f46e5)" }}
  >
    <Container size="md">
      <div style={{ color: "#fff", textAlign: "center", fontWeight: 600 }}>
        Section with background token
      </div>
    </Container>
  </Section>
);

style.description:
Inline styles — primarily for CSS variable-based background and border
overrides that follow the design token model.  Example:
  style={{ background: 'var(--section-hero-bg)' }}

stories.snippet:
const Column = () => (
  <Stack direction="col" gap={3}>
    <Tile label="Item 1" />
    <Tile label="Item 2" />
    <Tile label="Item 3" />
  </Stack>
);

const Row = () => (
  <Stack direction="row" gap={3}>
    <Tile label="Item 1" />
    <Tile label="Item 2" />
    <Tile label="Item 3" />
  </Stack>
);

const GapVariants = () => (
  <Stack direction="col" gap={8}>
    {([0, 2, 4, 6, 8, 12] as const).map((gap) => (
      <div key={gap}>
        <p style={{ fontSize: "0.75rem", color: "var(--text-muted)", marginBottom: "0.5rem" }}>
          gap={gap}
        </p>
        <Stack direction="row" gap={gap}>
          <Tile label="A" />
          <Tile label="B" />
          <Tile label="C" />
        </Stack>
      </div>
    ))}
  </Stack>
);

const Alignment = () => (
  <Stack direction="col" gap={6}>
    {(["start", "center", "end"] as const).map((align) => (
      <div key={align}>
        <p style={{ fontSize: "0.75rem", color: "var(--text-muted)", marginBottom: "0.5rem" }}>
          align=&quot;{align}&quot;
        </p>
        <Stack
          direction="row"
          gap={3}
          align={align}
          style={{ background: "var(--subtle, #f8fafc)", padding: "0.75rem", borderRadius: "0.5rem" }}
        >
          <Tile label="Short" />
          <Tile label="Taller item" width="6rem" />
          <Tile label="Item" />
        </Stack>
      </div>
    ))}
  </Stack>
);

const Justify = () => (
  <Stack direction="col" gap={6}>
    {(["start", "center", "end", "between"] as const).map((justify) => (
      <div key={justify}>
        <p style={{ fontSize: "0.75rem", color: "var(--text-muted)", marginBottom: "0.5rem" }}>
          justify=&quot;{justify}&quot;
        </p>
        <Stack
          direction="row"
          gap={3}
          justify={justify}
          style={{ background: "var(--subtle, #f8fafc)", padding: "0.75rem", borderRadius: "0.5rem" }}
        >
          <Tile label="A" />
          <Tile label="B" />
          <Tile label="C" />
        </Stack>
      </div>
    ))}
  </Stack>
);

const Wrapping = () => (
  <Stack direction="row" gap={3} wrap style={{ maxWidth: "20rem" }}>
    {["Alpha", "Beta", "Gamma", "Delta", "Epsilon", "Zeta", "Eta"].map((label) => (
      <Tile key={label} label={label} />
    ))}
  </Stack>
);

const SemanticElement = () => (
  <Stack as="ul" direction="col" gap={2} style={{ listStyle: "none", padding: 0, margin: 0 }}>
    <li><Tile label="List item 1" /></li>
    <li><Tile label="List item 2" /></li>
    <li><Tile label="List item 3" /></li>
  </Stack>
);

const Alignment = () => (
  <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem", maxWidth: "32rem" }}>
    <Text align="left">Left-aligned text (default)</Text>
    <Text align="center">Centre-aligned text</Text>
    <Text align="right">Right-aligned text</Text>
  </div>
);

