stories.snippet:
const AllVariants = () => (
  <div className="flex flex-wrap gap-2">
    <Badge variant="default">Default</Badge>
    <Badge variant="primary">Primary</Badge>
    <Badge variant="success" dot>Success</Badge>
    <Badge variant="warning" dot>Warning</Badge>
    <Badge variant="error"   dot>Error</Badge>
    <Badge variant="outline">Outline</Badge>
  </div>
);

const AllVariants = () => (
  <div className="flex flex-wrap items-center gap-3">
    <Button variant="primary">Primary</Button>
    <Button variant="secondary">Secondary</Button>
    <Button variant="outline">Outline</Button>
    <Button variant="ghost">Ghost</Button>
  </div>
);

const AllSizes = () => (
  <div className="flex flex-wrap items-end gap-3">
    <Button size="sm">Small</Button>
    <Button size="md">Medium</Button>
    <Button size="lg">Large</Button>
  </div>
);

const Default = () => <Card padding="md" shadow="sm" hover={false}>
    <p style={{ fontSize: "0.875rem" }}>Simple card content — no sub-components needed for basic use.</p>
</Card>;

const HoverEffect = () => <Card padding="md" shadow="sm" hover>
    <p style={{ fontSize: "0.875rem" }}>Hover over this card to see the shadow lift.</p>
</Card>;

const ShadowVariants = () => (
  <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
    {(["none", "sm", "md"] as const).map((shadow) => (
      <Card key={shadow} shadow={shadow}>
        <p style={{ fontSize: "0.875rem" }}>shadow=&quot;{shadow}&quot;</p>
      </Card>
    ))}
  </div>
);

const PaddingVariants = () => (
  <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
    {(["none", "sm", "md", "lg"] as const).map((padding) => (
      <Card key={padding} padding={padding}>
        <p style={{ fontSize: "0.875rem" }}>padding=&quot;{padding}&quot;</p>
      </Card>
    ))}
  </div>
);

const GridOfCards = () => (
  <div
    style={{
      display:               "grid",
      gridTemplateColumns:   "repeat(3, 1fr)",
      gap:                   "1.5rem",
      maxWidth:              "56rem",
    }}
  >
    {[
      { title: "Analytics",    desc: "Real-time dashboards and insights." },
      { title: "Integrations", desc: "Connect your favourite tools." },
      { title: "Security",     desc: "Enterprise-grade data protection." },
    ].map(({ title, desc }) => (
      <Card key={title} hover>
        <CardHeader>
          <h3 style={{ fontWeight: 600 }}>{title}</h3>
        </CardHeader>
        <CardContent>
          <p style={{ fontSize: "0.875rem", color: "var(--text-muted, #6b7280)" }}>{desc}</p>
        </CardContent>
      </Card>
    ))}
  </div>
);

const Default = () => <FormField label="Email address" htmlFor="email" required={false} hint="" error="">
    <Input id="email" name="email" type="email" placeholder="you@example.com" />
</FormField>;

const WithTextarea = () => <FormField label="Message" htmlFor="msg" required hint="" error="">
    <Textarea id="msg" name="message" placeholder="Your message…" rows={4} />
</FormField>;

const WithValue = () => <Input
    type="email"
    placeholder="Enter a value…"
    error={false}
    disabled={false}
    defaultValue="example@domain.com" />;

const ErrorState = () => <Input
    type="email"
    placeholder="Enter a value…"
    error
    disabled={false}
    defaultValue="bad-email" />;

const Disabled = () => <Input
    type="text"
    placeholder="Enter a value…"
    error={false}
    disabled
    defaultValue="Cannot be edited" />;

const AllVariants = () => (
  <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem", padding: "1rem" }}>
    {(["default", "primary", "muted", "underline", "nav"] as const).map((variant) => (
      <div key={variant} style={{ display: "flex", alignItems: "center", gap: "1rem" }}>
        <span style={{ width: "6rem", fontSize: "0.75rem", color: "var(--text-muted)" }}>{variant}</span>
        <Link href="/example" variant={variant}>
          Link text — {variant}
        </Link>
      </div>
    ))}
  </div>
);

const InProse = () => (
  <p style={{ fontSize: "1rem", lineHeight: "1.7", maxWidth: "36rem" }}>
    This paragraph contains an{" "}
    <Link href="/example" variant="underline">
      inline link with underline variant
    </Link>{" "}
    which is best suited for use within body copy where the link should be clearly
    distinguishable from surrounding text.
  </p>
);

const NavLinks = () => (
  <nav style={{ display: "flex", gap: "1.5rem", padding: "1rem", background: "white", borderBottom: "1px solid #e5e7eb" }}>
    {["Home", "Products", "Pricing", "Blog", "Contact"].map((label) => (
      <Link key={label} href="/example" variant="nav">
        {label}
      </Link>
    ))}
  </nav>
);

const Disabled = () => <Textarea
    rows={4}
    placeholder="Enter your message…"
    error={false}
    disabled
    defaultValue="Cannot be edited" />;
